/**
 * @method
 * @name dts_NOW_ALL_HD_LIST_OnLoadCompleted
 * @description dts_NOW_ALL_HD_LIST 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_NOW_ALL_HD_LIST_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page_3);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05937.dts_NOW_ALL_HD_LIST_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_NOW_ALL_HD_LIST_OnDblClick
 * @description grd_NOW_ALL_HD_LIST 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_NOW_ALL_HD_LIST_OnDblClick = async function(row, colid) {
    try {
        if (colid === "ISU_NM") {
            await scwin.openDetail3(row);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05937.grd_NOW_ALL_HD_LIST_OnDblClick" });
    }
};

