///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name openDetail3
 * @description open Detail3 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail3 = async function(row) {
    if (row > 0) {
        // 그리드에서 선택시
        scwin.clickIsuCd = dts_NOW_ALL_HD_LIST.getCellData(row, "ISU_CD");
        scwin.clickIsuKorAbbrv = dts_NOW_ALL_HD_LIST.getCellData(row, "ISU_NM");
        const options = {
            id: "ULDSTF35503",
            title: "개별종목보유수량조회",
            type: "pageFramePopup",
            width: "905px",
            height: 570 + 35
        };

        const data = {
            // TO-DO : 팝업으로 전달할 파라미터 설정
        };

        const result = await $c.win.openPopup("/lstmgt/ULDSTF35503.gfm", options, data);
        // TO-DO : result 값 확인 후 업무 로직 추가
    }
};

/**
 * @method
 * @name excelDown
 * @description excel Down 처리
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    $c.data.downloadGridViewExcel(grd_NOW_ALL_HD_LIST, {fileName: "당일전부보유리스트", type: "8"});
};

/**
 * @method
 * @name dscl
 * @description 안내문 작성  - 당일 전부보유목록
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    let vBzProcsNo = "";

    // 2010.07.23 업무처리번호 유무 - 정정공시를 위해
    await scwin.getBzProcsNo();
    vBzProcsNo = dts_BzProcsNo.getCellData(1, "BZ_PROCS_NO");
    if (vBzProcsNo === "") vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
    if (vBzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    await scwin.setLpNm3();
    // dts_DISC.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    let cont = 1;
    let overCheck = false;
    let tempK = 0;
    dts_DISC.setBroadcast(false);
    for (let i = 1; i <= dts_LP_NM_3.getRowCount(); i++) {
        let pLpMbtNm = "";
        let pIsuNm = "";
        let pCheck = false;
        let pcount = 0;
        const pLenStr = 0;
        const cnt = 1;
        for (let k = 1; k <= dts_NOW_ALL_HD_LIST.getRowCount(); k++) {
            if (overCheck) {
                k = tempK;
                overCheck = false;
            }
            if (dts_LP_NM_3.getCellData(i, "VALUE") === dts_NOW_ALL_HD_LIST.getCellData(k, "LP_MBR_NO")) {
                // pIsuNm =  pIsuNm + (pIsuNm == "" ? "" : ", ")  + dts_NOW_ALL_HD_LIST.NameString(k, "ISU_NM");
                pLpMbtNm = dts_LP_NM_3.getCellData(i, "TEXT");
                if (pcount > 0) {
                    pIsuNm = pIsuNm + ",";
                }
                if (pcount % 4 === 0 && pcount !== 0) pIsuNm = pIsuNm + "\n" + dts_NOW_ALL_HD_LIST.getCellData(k, "ISU_NM");

                else pIsuNm = pIsuNm + dts_NOW_ALL_HD_LIST.getCellData(k, "ISU_NM");
                pcount++;
                pCheck = true;
                if (pcount > 239) {
                    i--;
                    tempK = k + 1;
                    k = dts_NOW_ALL_HD_LIST.getRowCount() + 1;
                    overCheck = true;
                    pIsuNm = pIsuNm + ","; // SrM-000191426 ELW 상장공시시스템 개발 변경 추가 요구 사항

                }

            }
        }
        if (pCheck) {
            dts_DISC.insertRow();
            dts_DISC.setCellData(cont, "LP_MBR_NM", pLpMbtNm);
            dts_DISC.setCellData(cont, "ISU_NM", pIsuNm);
            cont++;
        }
    }
    dts_DISC.setBroadcast(true, true);
    scwin.getPar = function(arr, param_dts_NOW_ALL_HD_LIST, param_dts_NOW_DD, param_dts_DISC) {
        arr[0] = "99879";
        arr[1] = vBzProcsNo;
        arr[2] = '99999'; // 거래소코드
        arr[3] = '1'; // 시장구분

        $c.stf.copyDataSet(dts_NOW_ALL_HD_LIST, param_dts_NOW_ALL_HD_LIST);
        $c.stf.copyDataSet(dts_NOW_DD, param_dts_NOW_DD);
        $c.stf.copyDataSet(dts_DISC, param_dts_DISC);
        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 730 + 5;
    const hgt = 785 + 30;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "공시안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;
};
